 19	   * [Core Sync] 앱 기동 및 포그라운드 전환 시 호출되는 메인 동기화 파이프라인
 20	   */
 21	  async pullChanges(userId, rawToken) {
 22	    const now = new Date();
 23	    
 24	    // Time Windows 계산
 25	    const calWindowFrom = new Date(now.getTime() - (CALENDAR_PAST_DAYS * 24 * 60 * 60 * 1000));
 26	    const calWindowTo = new Date(now.getTime() + (CALENDAR_FUTURE_DAYS * 24 * 60 * 60 * 1000));
 27	    const msgWindowFrom = new Date(now.getTime() - (MESSAGING_PAST_DAYS * 24 * 60 * 60 * 1000));
 28	
 29	    // 1. 토큰 디코딩
 30	    const prevToken = SyncToken.decode(rawToken) || { ts: 0, d_ids: [], c_ids: [], s_ids: [] };
 31	    const previousSectionIds = Array.isArray(prevToken.s_ids) ? prevToken.s_ids : [];
 32	    const oldTsDate = prevToken.ts > 0 ? new Date(prevToken.ts * 1000) : null;
 33	
 34	    // 2. 현재 유저의 '진짜' 권한 조회 (DB 기준)
 35	    const [currDIds, currCIds] = await Promise.all([
 36	      SyncDAO.getBinderIdsByUserId(pool, userId),
 37	      SyncDAO.getSubscribedCalIdsByUserId(pool, userId),
 38	    ]);
 39	
 40	    if (!currDIds.length && !currCIds.length) {
 41	      return this._buildEmptyResponse(now, currDIds, currCIds);
 42	    }
 43	
 44	    // 3. Sync Context (상태 Diff) 객체 생성 - 이 객체 하나로 모든 DAO 쿼리가 동작합니다.
 45	    const ctx = {
 46	      userId,
 47	      oldTs: oldTsDate,
 48	      oldDIds: prevToken.d_ids.filter(id => currDIds.includes(id)), // 유지된 기존 바인더
 49	      oldCIds: prevToken.c_ids.filter(id => currCIds.includes(id)), // 유지된 기존 캘린더
 50	      newDIds: diff(currDIds, prevToken.d_ids), // 새로 가입한 바인더
 51	      newCIds: diff(currCIds, prevToken.c_ids), // 새로 구독한 캘린더
 52	      calWindowFrom,
 53	      calWindowTo,
 54	      msgWindowFrom
 55	    };
 56	
 57	    // ACL은 콘텐츠보다 먼저 읽어 revoke tombstone이 새 접근 필터에 가려지지 않게 한다.
 58	    const metaData = await this._fetchTrackAMeta(userId, currDIds, currCIds, oldTsDate);
 59	    const accessibleSectionIds = await SyncDAO.getAccessibleSectionIds(pool, userId, currDIds);
 60	    const accessReconciliation = {
 61	      hydrate_section_ids: diff(accessibleSectionIds, previousSectionIds),
 62	      purge_section_ids: diff(previousSectionIds, accessibleSectionIds),
 63	    };
 64	    ctx.hydrateSectionIds = accessReconciliation.hydrate_section_ids;
 65	
 66	    // 접근집합 재계산 뒤 hydrate/purge 지시를 확정한 다음 일반 delta를 조회한다.
 67	    const [calendarData, messagingData, personalData] = await Promise.all([
 68	      this._fetchTrackBCalendar(ctx),
 69	      this._fetchTrackCMessaging(ctx),
 70	      this._fetchPersonalData(userId, currDIds, oldTsDate, msgWindowFrom)
 71	    ]);
 72	
 73	    // 5. 다음 동기화를 위한 새 토큰 발급
 74	    const next_sync_token = SyncToken.encode({
 75	      ts: Math.floor(now.getTime() / 1000),
 76	      d_ids: currDIds,
 77	      c_ids: currCIds,
 78	      s_ids: accessibleSectionIds,
 79	    });
 80	    
 81	    return {
 82	      data: {
 83	        ...metaData,
 84	        access_reconciliation: accessReconciliation,
 85	        ...calendarData,
 86	        ...messagingData,
 87	        ...personalData,
 88	      },
 89	      next_sync_token
 90	    };
 91	  }
