122	    // 뼈대 데이터는 ts, old/new 따지지 않고 무조건 현재 소속 기준으로 100% 덮어씌움 (FK 에러 방지)
123	    const [binders, binderMembers, binderPreferences, binderSettings, users, groups, groupMembers, sectionGroups, section, calendars, subscribedCals] = await Promise.all([
