145	  async _fetchTrackBCalendar(ctx) {
146	    // 연쇄 호출(Cascading)의 악몽을 지우고, DAO 단에서 UNION ALL을 통해 각각 독립적으로 가져옵니다.
147	    const [events, eventInstances, eventParticipants, tasks, taskInstances, taskParticipants, specialDays] = await Promise.all([
148	      SyncDAO.getEventsDeltaFull(pool, ctx),
149	      SyncDAO.getEventInstancesDeltaFull(pool, ctx), // 부모(events) 참조 없이 독자 검사!
