154	      SyncDAO.getSpecialDaysDeltaFull(pool, ctx)
155	    ]);
156	
157	    return {
158	      events, event_instances: eventInstances, event_participants: eventParticipants,
159	      tasks, task_instances: taskInstances, task_participants: taskParticipants, special_days: specialDays
160	    };
