170	    const messageIds = messages.map(m => m.id);
171	    const relatedOldTs = ctx.hydrateSectionIds.length ? null : ctx.oldTs;
172	    const [attachments, embeds, reactions, mentions] = await Promise.all([
173	      SyncDAO.getMessageAttachments(pool, messageIds, relatedOldTs),
